function rrParse(pat){
  var i=0;
  function parseAlt(){
    var parts=[parseCat()];
    while(pat[i]==='|'){ i++; parts.push(parseCat()); }
    return parts.length===1?parts[0]:{type:'alt',options:parts};
  }
  function parseCat(){
    var parts=[];
    while(i<pat.length && pat[i]!=='|' && pat[i]!=')'){ parts.push(parseAtom()); }
    return parts.length===1?parts[0]:{type:'cat',parts:parts};
  }
  function parseAtom(){
    var node=parsePrimary();
    while(pat[i]==='*'||pat[i]==='+'||pat[i]==='?'){ node={type:'quant',q:pat[i],node:node}; i++; }
    return node;
  }
  function parsePrimary(){
    var c=pat[i];
    if(c==='('){ i++; var n=parseAlt(); if(pat[i]===')') i++; else throw new Error('缺少 )'); return {type:'group',node:n}; }
    if(c===')') throw new Error('多余的 )');
    if(c==='['){ i++; var cls=''; while(i<pat.length && pat[i]!==']'){ cls+=pat[i]; i++; } if(pat[i]===']') i++; else throw new Error('缺少 ]'); return {type:'class',chars:cls}; }
    if(c==='\\'){ i++; var e=pat[i]; i++; return {type:'esc',ch:e}; }
    if(c==='.'){ i++; return {type:'any'}; }
    i++; return {type:'lit',ch:c};
  }
  var ast=parseAlt();
  if(i<pat.length) throw new Error('未解析完: '+pat.slice(i));
  return ast;
}
function labelOf(n){
  if(n.type==='lit') return n.ch;
  if(n.type==='esc') return '\\'+n.ch;
  if(n.type==='any') return '.';
  if(n.type==='class') return '['+n.chars+']';
  return '?';
}
var GX=22, GAP=14, FORK=24, LOOP=22, PAD=14, BH=28;
function esc(s){ return String(s).replace(/[&<>]/g,function(c){ return {'&':'&amp;','<':'&lt;','>':'&gt;'}[c]; }); }
function Lleaf(label){
  var w=Math.max(40, label.length*8+18), h=BH, ey=h/2;
  return {w:w,h:h,ey:ey,svg:'<g><rect x="0" y="0" width="'+w+'" height="'+h+'" rx="6" fill="#141417" stroke="#5E6AD2" stroke-width="1.3"/><text x="'+(w/2)+'" y="'+(h/2+4)+'" text-anchor="middle" fill="#E4E4E7" font-size="12">'+esc(label)+'</text></g>'};
}
function Lnode(n){
  if(n.type==='lit'||n.type==='esc'||n.type==='any'||n.type==='class') return Lleaf(labelOf(n));
  if(n.type==='cat'){ var ch=n.parts.map(Lnode), w=0; ch.forEach(function(c,k){ w+=c.w; if(k) w+=GX; }); var h=Math.max.apply(null,ch.map(function(c){return c.h;})); var ey=h/2, svg='', x=0;
    for(var k=0;k<ch.length;k++){ var c=ch[k]; if(k){ svg+='<line x1="'+(x-GX)+'" y1="'+ey+'" x2="'+x+'" y2="'+ey+'" stroke="#3f3f46" stroke-width="1.4"/>'; } svg+='<g transform="translate('+x+','+(ey-c.ey)+')">'+c.svg+'</g>'; x+=c.w+(k<ch.length-1?GX:0); }
    return {w:w,h:h,ey:ey,svg:svg}; }
  if(n.type==='alt'){ var ch2=n.options.map(Lnode), innerW=Math.max.apply(null,ch2.map(function(c){return c.w;})), h2=0; ch2.forEach(function(c,k){ h2+=c.h; if(k) h2+=GAP; }); var w2=innerW+2*FORK, ey2=h2/2, svg2='', y=0;
    for(var k=0;k<ch2.length;k++){ var c=ch2[k], oy=y, cy=oy+c.ey, ex=FORK+c.w;
      svg2+='<path d="M0 '+ey2+' C'+(FORK*0.6)+' '+ey2+' '+(FORK*0.4)+' '+cy+' '+FORK+' '+cy+'" fill="none" stroke="#3f3f46" stroke-width="1.4"/>';
      svg2+='<g transform="translate('+FORK+','+oy+')">'+c.svg+'</g>';
      svg2+='<path d="M'+ex+' '+cy+' C'+(ex+(w2-ex)*0.4)+' '+cy+' '+(ex+(w2-ex)*0.6)+' '+ey2+' '+w2+' '+ey2+'" fill="none" stroke="#3f3f46" stroke-width="1.4"/>';
      y+=c.h+(k<ch2.length-1?GAP:0); }
    return {w:w2,h:h2,ey:ey2,svg:svg2}; }
  if(n.type==='quant'){ var c=Lnode(n.node), h=c.h+LOOP, w=c.w+2*PAD, ey=c.ey+LOOP, svg='<g transform="translate('+PAD+','+LOOP+')">'+c.svg+'</g>';
    if(n.q==='*'||n.q==='+'){ svg+='<path d="M0 '+ey+' C'+(w*0.2)+' '+(LOOP*0.2)+' '+(w*0.8)+' '+(LOOP*0.2)+' '+w+' '+ey+'" fill="none" stroke="#A78BFA" stroke-width="1.4" stroke-dasharray="'+(n.q==='+'?'0':'4 3')+'"/>';
      if(n.q==='*') svg+='<line x1="0" y1="'+ey+'" x2="'+w+'" y2="'+ey+'" stroke="#3f3f46" stroke-width="1" stroke-dasharray="2 3" opacity="0.5"/>'; }
    else { svg+='<path d="M0 '+ey+' C'+(w*0.2)+' '+(LOOP*0.2)+' '+(w*0.8)+' '+(LOOP*0.2)+' '+w+' '+ey+'" fill="none" stroke="#A78BFA" stroke-width="1.4" stroke-dasharray="4 3"/>'; }
    return {w:w,h:h,ey:ey,svg:svg}; }
  if(n.type==='group'){ var c=Lnode(n.node); return {w:c.w+2*PAD,h:c.h,ey:c.ey,svg:'<g transform="translate('+PAD+',0)">'+c.svg+'</g>'}; }
  var l=Lleaf('?'); return l;
}
function rrSvg(ast){
  var L=Lnode(ast), PADX=20, PADY=20;
  var W=L.w+2*PADX, H=L.h+2*PADY;
  return '<svg xmlns="http://www.w3.org/2000/svg" width="'+W+'" height="'+H+'" viewBox="0 0 '+W+' '+H+'">'
    +'<rect width="'+W+'" height="'+H+'" fill="#0A0A0B"/>'
    +'<circle cx="'+PADX+'" cy="'+(PADY+L.ey)+'" r="4" fill="#10B981"/>'
    +'<g transform="translate('+PADX+','+PADY+')">'+L.svg+'</g>'
    +'<circle cx="'+(PADX+L.w)+'" cy="'+(PADY+L.ey)+'" r="4" fill="#EF4444"/></svg>';
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { rrParse:rrParse, rrSvg:rrSvg };
}
if (typeof window !== 'undefined') {
  window.RegexRailForgePure = { rrParse:rrParse, rrSvg:rrSvg };
}
